	('9105fb9e-fe95-4253-9f4b-b9d35d87daaf', 'Jelaskan langkah-langkah troubleshooting yang harus dilakukan ketika komputer client tidak dapat mengakses internet, padahal komputer lain dalam jaringan yang sama dapat mengakses internet dengan normal! Berikan minimal 5 langkah troubleshooting secara berurutan!', 'essay', '{TKJ,troubleshooting,jaringan,internet}', 'medium', 'f853e15b-3401-4b70-89fc-f7831f30826e', '2025-08-19 11:35:43.974324+00', '2025-08-19 11:35:43.974324+00', NULL, NULL),
	('baabecf5-5156-46cb-9546-4a39faa2c983', 'Perusahaan ABC memiliki 3 departemen (IT, Finance, Marketing) yang ingin dipisahkan jaringannya untuk keamanan. Jelaskan bagaimana cara mengimplementasikan VLAN untuk memisahkan ketiga departemen tersebut! Sertakan konfigurasi dasar switch dan keuntungan penggunaan VLAN!', 'essay', '{TKJ,VLAN,switch,konfigurasi}', 'hard', 'f853e15b-3401-4b70-89fc-f7831f30826e', '2025-08-19 11:35:43.974324+00', '2025-08-19 11:35:43.974324+00', NULL, NULL),
	('95126ec6-a79c-4c8d-9c14-f8b9278a1a76', 'Sebutkan dan jelaskan minimal 4 metode keamanan yang dapat diterapkan pada jaringan wireless (WiFi) untuk melindungi dari ancaman keamanan! Berikan contoh implementasinya pada router WiFi!', 'essay', '{TKJ,wireless,WiFi,keamanan}', 'medium', 'f853e15b-3401-4b70-89fc-f7831f30826e', '2025-08-19 11:35:43.974324+00', '2025-08-19 11:35:43.974324+00', NULL, NULL),
	('a840fb28-1b20-49e6-ae99-f5eac69c2f4b', 'Jelaskan pentingnya network monitoring dalam pengelolaan jaringan komputer! Sebutkan minimal 3 tools/software yang dapat digunakan untuk monitoring jaringan dan jelaskan fungsi masing-masing!', 'essay', '{TKJ,monitoring,jaringan,tools}', 'medium', 'f853e15b-3401-4b70-89fc-f7831f30826e', '2025-08-19 11:35:43.974324+00', '2025-08-19 11:35:43.974324+00', NULL, NULL),
