	('0a827409-2a41-4bbd-8051-d2ad4e7bbb1a', 'Jelaskan tahapan-tahapan dalam analisis sistem informasi! Mengapa tahap analisis ini penting dalam pengembangan software? Berikan contoh deliverable yang dihasilkan dari setiap tahapan analisis!', 'essay', '{RPL,"analisis sistem",SDLC,requirement}', 'medium', 'f853e15b-3401-4b70-89fc-f7831f30826e', '2025-08-19 11:35:43.974324+00', '2025-08-19 11:35:43.974324+00', NULL, NULL),
	('bd8e8e57-88e4-42b5-865b-07f9c540f477', 'Sebuah sekolah ingin membuat sistem informasi akademik. Buatlah desain database sederhana yang mencakup entitas Siswa, Guru, Mata Pelajaran, dan Nilai! Jelaskan relasi antar tabel dan berikan contoh field untuk setiap tabel!', 'essay', '{RPL,database,ERD,desain}', 'hard', 'f853e15b-3401-4b70-89fc-f7831f30826e', '2025-08-19 11:35:43.974324+00', '2025-08-19 11:35:43.974324+00', NULL, NULL),
	('c8adb7de-53e6-4309-abab-63c2ce1648e8', 'Jelaskan 4 konsep dasar dalam Object-Oriented Programming (OOP)! Berikan contoh implementasi sederhana dari setiap konsep tersebut dalam bahasa pemrograman yang Anda kuasai!', 'essay', '{RPL,OOP,pemrograman,konsep}', 'medium', 'f853e15b-3401-4b70-89fc-f7831f30826e', '2025-08-19 11:35:43.974324+00', '2025-08-19 11:35:43.974324+00', NULL, NULL),
	('2d91bb8c-ca80-4132-9f1a-2e2637c5fa4f', 'Jelaskan perbedaan antara Black Box Testing dan White Box Testing! Berikan contoh skenario testing untuk sebuah fungsi login pada aplikasi web menggunakan kedua metode tersebut!', 'essay', '{RPL,testing,"black box","white box"}', 'hard', 'f853e15b-3401-4b70-89fc-f7831f30826e', '2025-08-19 11:35:43.974324+00', '2025-08-19 11:35:43.974324+00', NULL, NULL),
	('28ebd70c-c687-4291-be24-a8451b6d8f9e', 'Anda ditugaskan sebagai project manager untuk mengembangkan aplikasi e-commerce dalam waktu 6 bulan. Jelaskan bagaimana Anda akan merencanakan dan mengelola project ini! Sebutkan tools yang akan digunakan dan bagaimana cara mengatur timeline project!', 'essay', '{RPL,"project management",planning,tools}', 'hard', 'f853e15b-3401-4b70-89fc-f7831f30826e', '2025-08-19 11:35:43.974324+00', '2025-08-19 11:35:43.974324+00', NULL, NULL),
	('1e1ab7a8-dd26-437f-8fb1-2895babffad9', 'Protokol yang digunakan untuk mengirim email melalui internet adalah...', 'multiple_choice', '{TKJ,jaringan,protokol,email}', 'easy', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-08-20 17:37:58.118646+00', '2025-08-20 17:37:58.118646+00', '[{"id": "A", "text": "HTTP"}, {"id": "B", "text": "SMTP"}, {"id": "C", "text": "FTP"}, {"id": "D", "text": "DHCP"}, {"id": "E", "text": "DNS"}]', 'B'),
	('c2f596ce-b5a6-4277-b78c-09cdc1c648b7', 'Layer pada model OSI yang bertanggung jawab untuk routing adalah...', 'multiple_choice', '{TKJ,jaringan,OSI,routing}', 'medium', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-08-20 17:37:58.118646+00', '2025-08-20 17:37:58.118646+00', '[{"id": "A", "text": "Physical Layer"}, {"id": "B", "text": "Data Link Layer"}, {"id": "C", "text": "Network Layer"}, {"id": "D", "text": "Transport Layer"}, {"id": "E", "text": "Session Layer"}]', 'C'),
	('84b8dc06-3122-42ec-8745-610c07a204a3', 'IP Address 192.168.1.100/24 memiliki subnet mask...', 'multiple_choice', '{TKJ,jaringan,"IP address",subnet}', 'medium', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-08-20 17:37:58.118646+00', '2025-08-20 17:37:58.118646+00', '[{"id": "A", "text": "255.255.255.0"}, {"id": "B", "text": "255.255.0.0"}, {"id": "C", "text": "255.0.0.0"}, {"id": "D", "text": "255.255.255.128"}, {"id": "E", "text": "255.255.255.192"}]', 'A'),
	('1e212289-039b-4d3e-91dd-18f8a44e9c24', 'Perangkat yang berfungsi untuk menghubungkan beberapa jaringan yang berbeda adalah...', 'multiple_choice', '{TKJ,hardware,jaringan,router}', 'easy', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-08-20 17:37:58.118646+00', '2025-08-20 17:37:58.118646+00', '[{"id": "A", "text": "Hub"}, {"id": "B", "text": "Switch"}, {"id": "C", "text": "Router"}, {"id": "D", "text": "Bridge"}, {"id": "E", "text": "Repeater"}]', 'C'),
	('08815e32-10ff-4dbd-b8b2-094a5962552a', 'Teknik enkripsi yang menggunakan kunci publik dan kunci privat adalah...', 'multiple_choice', '{TKJ,keamanan,enkripsi,kriptografi}', 'hard', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-08-20 17:37:58.118646+00', '2025-08-20 17:37:58.118646+00', '[{"id": "A", "text": "Symmetric Encryption"}, {"id": "B", "text": "Asymmetric Encryption"}, {"id": "C", "text": "Hash Function"}, {"id": "D", "text": "Digital Signature"}, {"id": "E", "text": "Firewall"}]', 'B'),
	('52055313-f1e1-4945-bbb1-ac7abe463eb3', 'Jelaskan langkah-langkah troubleshooting yang harus dilakukan ketika komputer client tidak dapat mengakses internet, padahal komputer lain dalam jaringan yang sama dapat mengakses internet dengan normal! Berikan minimal 5 langkah troubleshooting secara berurutan!', 'essay', '{TKJ,troubleshooting,jaringan,internet}', 'medium', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-08-20 17:37:58.118646+00', '2025-08-20 17:37:58.118646+00', NULL, NULL),
	('749046b9-07a0-4651-8509-cf67c226a4c7', 'Perusahaan ABC memiliki 3 departemen (IT, Finance, Marketing) yang ingin dipisahkan jaringannya untuk keamanan. Jelaskan bagaimana cara mengimplementasikan VLAN untuk memisahkan ketiga departemen tersebut! Sertakan konfigurasi dasar switch dan keuntungan penggunaan VLAN!', 'essay', '{TKJ,VLAN,switch,konfigurasi}', 'hard', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-08-20 17:37:58.118646+00', '2025-08-20 17:37:58.118646+00', NULL, NULL),
	('6b89809a-9d8c-4cc0-bfed-2f6340ba5f40', 'Sebutkan dan jelaskan minimal 4 metode keamanan yang dapat diterapkan pada jaringan wireless (WiFi) untuk melindungi dari ancaman keamanan! Berikan contoh implementasinya pada router WiFi!', 'essay', '{TKJ,wireless,WiFi,keamanan}', 'medium', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-08-20 17:37:58.118646+00', '2025-08-20 17:37:58.118646+00', NULL, NULL),
	('bd8bdb22-0ef0-46ff-aad6-443760dba5da', 'Jelaskan pentingnya network monitoring dalam pengelolaan jaringan komputer! Sebutkan minimal 3 tools/software yang dapat digunakan untuk monitoring jaringan dan jelaskan fungsi masing-masing!', 'essay', '{TKJ,monitoring,jaringan,tools}', 'medium', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-08-20 17:37:58.118646+00', '2025-08-20 17:37:58.118646+00', NULL, NULL),
	('7805df51-ee16-44b4-b60b-e42d82f4b86f', 'Jelaskan perbedaan antara Web Server, Database Server, dan File Server! Berikan contoh software untuk masing-masing jenis server dan jelaskan skenario penggunaan yang tepat untuk setiap jenis server tersebut!', 'essay', '{TKJ,server,administration,"web server"}', 'hard', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-08-20 17:37:58.118646+00', '2025-08-20 17:37:58.118646+00', NULL, NULL),
	('6a4bddd1-19a4-458f-8a40-701aea824890', 'siapa presiden RI ke-6', 'essay', '{Umum}', 'medium', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-09-05 12:11:16.822098+00', '2025-09-05 12:11:16.822098+00', NULL, 'Susilo Bambang Yudhoyono (SBY)'),
	('ad63007c-bff8-4ce6-828f-3210f58084f1', 'Perangkat yang berfungsi sebagai pusat penghubung jaringan pada topologi star adalah ...', 'multiple_choice', '{"Teknik Jaringan Komputer Telekomunikasi","Kelas 10"}', 'easy', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-09-18 07:05:12.073428+00', '2025-09-18 07:05:12.073428+00', '[{"text": "Router", "label": "A"}, {"text": "Switch", "label": "B"}, {"text": "Repeater", "label": "C"}, {"text": "Bridge", "label": "D"}]', 'B'),
	('51f868ec-462e-44dc-b97c-eeaef316289f', 'Jelaskan fungsi utama kabel UTP pada jaringan komputer!', 'essay', '{"Teknik Jaringan Komputer Telekomunikasi","Kelas 10"}', 'easy', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-09-18 07:05:12.073428+00', '2025-09-18 07:05:12.073428+00', NULL, 'Menghubungkan perangkat jaringan untuk transmisi data dengan kecepatan tinggi dan meminimalisir interferensi pada jaringan LAN'),
	('eeb1a140-99ca-4545-b9f6-d16ec9850b71', 'Sebutkan kelebihan dan kekurangan topologi bus dalam jaringan komputer!', 'essay', '{"Teknik Jaringan Komputer Telekomunikasi","Kelas 10"}', 'medium', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-09-18 07:05:12.073428+00', '2025-09-18 07:05:12.073428+00', NULL, 'Kelebihan: biaya murah dan instalasi sederhana; Kekurangan: sulit troubleshooting dan mudah terjadi collision saat trafik tinggi'),
	('288e5ab6-54d8-4f41-affb-7bcc621de3b6', 'Jelaskan peran NIC (Network Interface Card) dalam komunikasi data di jaringan!', 'essay', '{"Teknik Jaringan Komputer Telekomunikasi","Kelas 10"}', 'hard', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-09-18 07:05:12.073428+00', '2025-09-18 07:05:12.073428+00', NULL, 'NIC bertugas menghubungkan komputer ke jaringan, mengubah data menjadi sinyal jaringan dan sebaliknya'),
	('1d0bb7c2-a2bb-41ed-b5ff-c9391afb6eb7', 'Sebutkan dan jelaskan perbedaan mendasar antara IPv4 dan IPv6!', 'essay', '{"Teknik Jaringan Komputer Telekomunikasi","Kelas 11"}', 'medium', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-09-18 07:05:12.073428+00', '2025-09-18 07:05:12.073428+00', NULL, 'IPv4 menggunakan alamat 32-bit dengan format desimal (4 oktet), IPv6 menggunakan alamat 128-bit dengan format heksadesimal sehingga mendukung lebih banyak alamat dan fitur keamanan lebih baik'),
	('f09f7eea-e3c0-4349-9904-bc45a615e10e', 'Jelaskan konsep dasar VLAN (Virtual Local Area Network) dan manfaatnya dalam pengelolaan jaringan!', 'essay', '{"Teknik Jaringan Komputer Telekomunikasi","Kelas 11"}', 'hard', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-09-18 07:05:12.073428+00', '2025-09-18 07:05:12.073428+00', NULL, 'VLAN adalah pemisahan jaringan secara logis pada switch sehingga perangkat dapat dikelompokkan tanpa memandang lokasi fisik; manfaatnya meningkatkan keamanan, efisiensi, dan manajemen trafik'),
	('cec130d9-517d-4593-a565-dcf177382e5f', 'Jenis kabel yang sering digunakan untuk jaringan LAN pada standar IEEE 802.3 adalah ...', 'multiple_choice', '{"Teknik Jaringan Komputer Telekomunikasi","Kelas 10"}', 'medium', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-09-18 07:06:17.310737+00', '2025-09-18 07:06:17.310737+00', '[{"text": "Coaxial", "label": "A"}, {"text": "Fiber Optic", "label": "B"}, {"text": "UTP", "label": "C"}, {"text": "STP", "label": "D"}]', 'C'),
	('1a8ec049-9a1a-4b44-b865-c6c96854c40e', 'Sebutkan kelebihan dan kekurangan topologi bus dalam jaringan komputer!', 'essay', '{"Teknik Jaringan Komputer Telekomunikasi","Kelas 10"}', 'medium', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-09-18 07:06:17.310737+00', '2025-09-18 07:06:17.310737+00', NULL, 'Kelebihan: biaya murah dan instalasi sederhana; Kekurangan: sulit troubleshooting dan mudah terjadi collision saat trafik tinggi'),
	('e864a722-0d33-442e-bbfc-1fe6b6ca989f', 'Protokol yang digunakan untuk mentransfer file antar komputer dalam jaringan adalah ...', 'multiple_choice', '{"Teknik Jaringan Komputer Telekomunikasi","Kelas 11"}', 'easy', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-09-18 07:06:17.310737+00', '2025-09-18 07:06:17.310737+00', '[{"text": "FTP", "label": "A"}, {"text": "HTTP", "label": "B"}, {"text": "SMTP", "label": "C"}, {"text": "POP3", "label": "D"}]', 'A'),
	('bf33320c-8274-4087-82d2-ea29fd6031d5', 'Perangkat jaringan yang dapat membagi jaringan menjadi beberapa segmen sekaligus mengurangi collision domain adalah ...', 'multiple_choice', '{"Teknik Jaringan Komputer Telekomunikasi","Kelas 11"}', 'medium', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-09-18 07:06:17.310737+00', '2025-09-18 07:06:17.310737+00', '[{"text": "Hub", "label": "A"}, {"text": "Switch", "label": "B"}, {"text": "Repeater", "label": "C"}, {"text": "Bridge", "label": "D"}]', 'B'),
	('4688b7b1-eee0-4dc6-a517-823c2910744b', 'Uraikan langkah-langkah konfigurasi dasar pada router MikroTik untuk menghubungkan dua jaringan!', 'essay', '{"Teknik Jaringan Komputer Telekomunikasi","Kelas 11"}', 'hard', '97d036af-e1f2-4c5b-a8be-e5a8b6ca2718', '2025-09-18 07:06:17.310737+00', '2025-09-18 07:06:17.310737+00', NULL, '1. Atur IP address pada interface masing-masing jaringan, 2. Atur default gateway atau routing, 3. Aktifkan NAT jika diperlukan, 4. Uji konektivitas dengan ping antar jaringan');
